// Theme derivation rule and the PROPOSED v3 candidate table (T-012;
// ESC-002; ADVISOR_REPLY-002 Actions 1–3; erratum SE-13; VTG-01…VTG-10).
//
// 1. Unit tests of lib/design/tokens/theme_derivation.dart (rule written in
//    docs/agents/tasks/T-012.md, "Derivation rule").
// 2. design/brand/themes-v3-candidate.json (generated by
//    tool/ui_check/make_theme_candidates.py): the Dart rule re-derives every
//    role from themes-v2.json + the proposed owner values and must match
//    byte for byte; then the full VTG set runs per theme and must pass.
// Nothing here touches design/tokens/design_tokens.json (v1.1 still binds
// code, SE-13 interim rule).

import 'dart:convert';
import 'dart:io';

import 'package:bluehesab_mini/design/tokens/contrast_guard.dart';
import 'package:bluehesab_mini/design/tokens/theme_derivation.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_test/flutter_test.dart';

const String v2Path = 'design/brand/themes-v2.json';
const String candidatePath = 'design/brand/themes-v3-candidate.json';
const String tokensPath = 'design/tokens/design_tokens.json';

int rgbOf(String hex) => int.parse(hex.substring(1), radix: 16);

String hexOf(int rgb) =>
    '#${rgb.toRadixString(16).padLeft(6, '0').toUpperCase()}';

Map<String, Object?> obj(Object? value) => value! as Map<String, Object?>;

Map<String, Object?> readJson(String path) =>
    jsonDecode(File(path).readAsStringSync()) as Map<String, Object?>;

/// One VTG pair: foreground role, background role, threshold.
typedef VtgPair = (String fg, String bg, double threshold);

String textFg(String fill) => fill == 'primary' ? 'primary-text' : fill;

/// VTG-01…VTG-10 over a derived theme (table 11-3; `primary` as text is
/// `primary-text`, ADVISOR_REPLY-002; Clay exception per SE-13).
Map<String, List<VtgPair>> vtgPairs({required bool backgroundCarriesText}) {
  final List<String> ts =
      textSurfaces(backgroundCarriesText: backgroundCarriesText);
  final List<String> fills = <String>[...accentRoles, ...semanticRoles];
  return <String, List<VtgPair>>{
    'VTG-01': <VtgPair>[
      for (final String f in <String>['text-primary', 'text-secondary'])
        for (final String b in ts) (f, b, 4.5),
      if (!backgroundCarriesText) ...<VtgPair>[
        ('on_bg_text', 'background', 4.5),
        ('on_bg_text2', 'background', 3),
      ],
    ],
    'VTG-02': <VtgPair>[
      for (final String f in fills)
        for (final String b in ts) (textFg(f), b, 4.5),
    ],
    'VTG-03': <VtgPair>[
      for (final String f in fills)
        for (final String s in <String>['', '-hover', '-pressed'])
          ('on-fill', '$f$s', 4.5),
    ],
    'VTG-04': <VtgPair>[
      for (final String f in fills) (textFg(f), '$f-subtle', 4.5),
      for (final String f in fills) ('text-primary', '$f-subtle', 4.5),
    ],
    'VTG-05': <VtgPair>[('inverse-text', 'inverse-surface', 4.5)],
    'VTG-06': <VtgPair>[for (final String b in ts) ('border-strong', b, 3)],
    'VTG-07': <VtgPair>[for (final String f in accentRoles) (f, 'ring-track', 3)],
    'VTG-08': <VtgPair>[
      for (final String f in fills)
        for (final String b in ts) (f, b, 3),
    ],
    'VTG-09': <VtgPair>[for (final String b in ts) ('focus-ring', b, 3)],
    'VTG-10': <VtgPair>[
      for (final String f in <String>[
        'primary',
        'text-secondary',
        'border-strong',
      ])
        (f, 'surface', 3.3),
    ],
  };
}

/// The 46 roles of table A-2-a, read from the v1 token file (light set).
List<String> contractRoles() =>
    obj(obj(readJson(tokensPath)['color'])['light']).keys.toList();

ThemeSource sourceOf(String id, Map<String, Object?> v2Theme,
    Map<String, Object?> candidateTheme) {
  final Map<String, Object?> roles = obj(v2Theme['roles']);
  final Map<String, Object?> owner = obj(candidateTheme['owner_values']);
  return ThemeSource(
    roles: <String, int>{
      for (final MapEntry<String, Object?> e in roles.entries)
        e.key: rgbOf(e.value! as String),
    },
    ownerFills: <String, int>{
      for (final String f in ownerFillRoles)
        f: rgbOf(obj(owner[f])['proposed']! as String),
    },
    backgroundCarriesText: candidateTheme['background_carries_text']! as bool,
  );
}

void main() {
  final Map<String, Object?> v2Themes = obj(readJson(v2Path)['themes']);
  final Map<String, Object?> candidate = readJson(candidatePath);
  final Map<String, Object?> candThemes = obj(candidate['themes']);

  group('derivation rule', () {
    test('state-layer opacities equal the state-opacity tokens', () {
      final Map<String, Object?> so = obj(readJson(tokensPath)['state-opacity']);
      expect(hoverLayer, so['hover-layer']);
      expect(pressedLayer, so['pressed-layer']);
    });

    test('mixRgb moves each channel by the share and rounds', () {
      expect(mixRgb(0x000000, 0xFFFFFF, 0.5), 0x808080);
      expect(mixRgb(0x123456, 0x123456, 0.3), 0x123456);
      expect(mixRgb(0xFFFFFF, 0x000000, 0), 0xFFFFFF);
      expect(mixRgb(0xFFFFFF, 0x000000, 1), 0x000000);
    });

    test('hover/pressed move toward text-primary (light theme)', () {
      final (int h, int p) = stateShades(0xB91C1C, 0x0E0B05, 0xFBF6EA);
      expect(h, mixRgb(0xB91C1C, 0x0E0B05, 0.08));
      expect(p, mixRgb(0xB91C1C, 0x0E0B05, 0.12));
      expect(relativeLuminanceRgb(p), lessThan(relativeLuminanceRgb(h)));
    });

    test('a fill at the ink end moves toward on-fill instead (Ivory primary)',
        () {
      final (int h, int p) = stateShades(0x0E0B05, 0x0E0B05, 0xFBF6EA);
      expect(h, mixRgb(0x0E0B05, 0xFBF6EA, 0.08));
      expect(p, mixRgb(0x0E0B05, 0xFBF6EA, 0.12));
      expect(p, isNot(0x0E0B05));
    });

    test('subtle share is 8 % on light and 16 % on dark surfaces', () {
      expect(subtleTint(0x000000, 0xFFFFFF), mixRgb(0xFFFFFF, 0, 0.08));
      expect(subtleTint(0xFFFFFF, 0x111111), mixRgb(0x111111, 0xFFFFFF, 0.16));
    });

    test('nearestShadeWhere keeps an accepted colour and finds the nearest',
        () {
      expect(nearestShadeWhere(0x123456, (int c) => true), 0x123456);
      expect(nearestShadeWhere(0x123456, (int c) => false), isNull);
      // Must pass 4.5:1 on white and on light grey: darker, never lighter.
      final int? s = nearestShadeWhere(
        0xB4492F,
        (int c) =>
            contrastRatioRgb(c, 0xFFFFFF) >= 4.5 &&
            contrastRatioRgb(c, 0xEEEEEE) >= 4.5,
      );
      expect(s, isNotNull);
      expect(contrastRatioRgb(s!, 0xEEEEEE), greaterThanOrEqualTo(4.5));
      expect(relativeLuminanceRgb(s), lessThan(relativeLuminanceRgb(0xB4492F)));
    });

    test('derived role set = 46 contract roles + primary-text', () {
      final Map<String, int> roles = deriveThemeRoles(sourceOf(
          'ivory', obj(v2Themes['ivory']), obj(candThemes['ivory'])));
      expect(roles.keys.toSet(),
          <String>{...contractRoles(), 'primary-text'});
      expect(roles, hasLength(47));
    });

    test('primary-text equals primary when primary already passes (Plum)', () {
      final Map<String, int> roles = deriveThemeRoles(
          sourceOf('plum', obj(v2Themes['plum']), obj(candThemes['plum'])));
      expect(roles['primary-text'], roles['primary']);
    });

    test('Clay: accent stays the fill, primary-text is a darker passing shade',
        () {
      final Map<String, int> roles = deriveThemeRoles(
          sourceOf('clay', obj(v2Themes['clay']), obj(candThemes['clay'])));
      expect(hexOf(roles['primary']!), '#B4492F');
      expect(roles['primary-text'], isNot(roles['primary']));
      for (final String s in <String>['surface', 'surface-raised']) {
        expect(contrastRatioRgb(roles['primary-text']!, roles[s]!),
            greaterThanOrEqualTo(4.5));
      }
    });

    test('negative control: Clay with background as a text surface throws',
        () {
      final ThemeSource clay =
          sourceOf('clay', obj(v2Themes['clay']), obj(candThemes['clay']));
      expect(
        () => deriveThemeRoles(ThemeSource(
            roles: clay.roles,
            ownerFills: clay.ownerFills)),
        throwsStateError,
      );
    });
  });

  group('themes-v3 candidate (PROPOSED)', () {
    test('status is PROPOSED and the themes match themes-v2', () {
      expect(candidate['status'], 'PROPOSED');
      expect(candThemes.keys.toList(), v2Themes.keys.toList());
      for (final Object? t in candThemes.values) {
        expect(obj(obj(t)['owner_values']).keys.toList(), ownerFillRoles);
      }
    });

    for (final String id in <String>['ivory', 'plum', 'clay', 'glow']) {
      test('theme $id: Dart rule reproduces every derived value', () {
        final Map<String, Object?> cand = obj(candThemes[id]);
        final Map<String, int> roles =
            deriveThemeRoles(sourceOf(id, obj(v2Themes[id]), cand));
        final Map<String, Object?> stored = obj(cand['derived']);
        expect(
          <String, String>{
            for (final MapEntry<String, int> e in roles.entries)
              e.key: hexOf(e.value),
          },
          <String, String>{
            for (final MapEntry<String, Object?> e in stored.entries)
              e.key: e.value! as String,
          },
        );
      });

      test('theme $id: VTG-01…VTG-10 all pass; counts and minima as stored',
          () {
        final Map<String, Object?> cand = obj(candThemes[id]);
        final Map<String, Object?> v2 = obj(v2Themes[id]);
        final bool bgText = cand['background_carries_text']! as bool;
        final Map<String, int> roles = <String, int>{
          ...deriveThemeRoles(sourceOf(id, v2, cand)),
          'on_bg_text': rgbOf(v2['on_bg_text']! as String),
          'on_bg_text2': rgbOf(v2['on_bg_text2']! as String),
        };
        final Map<String, Object?> stored = obj(cand['vtg']);
        int counted = 0;
        final List<String> report = <String>[];
        vtgPairs(backgroundCarriesText: bgText)
            .forEach((String gid, List<VtgPair> pairs) {
          double min = double.infinity;
          for (final (String fg, String bg, double th) in pairs) {
            final double r = contrastRatioRgb(roles[fg]!, roles[bg]!);
            expect(r, greaterThanOrEqualTo(th),
                reason: '$id $gid $fg on $bg: ${r.toStringAsFixed(3)} < $th');
            if (r < min) {
              min = r;
            }
          }
          final Map<String, Object?> s = obj(stored[gid]);
          expect(s['count'], pairs.length, reason: '$id $gid count');
          expect(min, closeTo((s['min']! as num).toDouble(), 0.006),
              reason: '$id $gid min');
          if (gid != 'VTG-10') {
            counted += pairs.length;
          }
          report.add('$gid ${pairs.length}/${min.toStringAsFixed(2)}');
        });
        expect(counted, bgText ? 105 : 87);
        debugPrint('themes-v3 candidate $id: VTG-01..09 $counted pairs, '
            '0 failing; ${report.join(', ')}');
      });
    }
  });
}
